# Generated by the AMP Nimbus instance template.
param(
    [Parameter(Mandatory = $true)][string]$Root,
    [Parameter(Mandatory = $true)][string]$Components
)

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

$repo = 'StratumServer/Nimbus'
$comps = @($Components -split '[,\s]+' | Where-Object { $_ -ne '' })
$headers = @{ 'User-Agent' = 'AMP-Nimbus-Template'; 'Accept' = 'application/vnd.github+json' }
if ($env:GITHUB_TOKEN) { $headers['Authorization'] = "Bearer $($env:GITHUB_TOKEN)" }

$tag = if ($env:NIMBUS_TAG) { $env:NIMBUS_TAG.Trim() } else { '' }
if ($tag -eq '') {
    $channel = if ($env:NIMBUS_CHANNEL) { $env:NIMBUS_CHANNEL } else { 'stable' }
    Write-Host "[AMP] resolving Nimbus release (channel=$channel)"
    $releases = Invoke-RestMethod -Headers $headers -Uri "https://api.github.com/repos/$repo/releases?per_page=100"
    $candidates = @($releases | Where-Object { -not $_.draft })
    if ($channel -ne 'prerelease') { $candidates = @($candidates | Where-Object { -not $_.prerelease }) }
    if ($candidates.Count -eq 0) { throw "No Nimbus release matched channel=$channel" }
    $tag = $candidates[0].tag_name
}
if (-not $tag.StartsWith('v')) { $tag = "v$tag" }

$marker = Join-Path $Root '.amp-nimbus-release'
if ((Test-Path $marker) -and ((Get-Content $marker -Raw).Trim() -eq $tag)) {
    $missing = @($comps | Where-Object { -not (Test-Path (Join-Path $Root $_)) })
    if ($missing.Count -eq 0) {
        Write-Host "[AMP] already on Nimbus $tag; nothing to download"
        exit 0
    }
}

$extract = Join-Path $Root '.nimbus-extract'
if (Test-Path $extract) { Remove-Item $extract -Recurse -Force }
New-Item -ItemType Directory -Force -Path $extract | Out-Null

$zip = Join-Path $Root 'nimbus-release.zip'
$url = "https://github.com/$repo/releases/download/$tag/Nimbus-$tag.zip"
Write-Host "[AMP] downloading $url"
Invoke-WebRequest -UseBasicParsing -Headers $headers -Uri $url -OutFile $zip
Expand-Archive -Path $zip -DestinationPath $extract -Force
Remove-Item $zip -Force

$src = Join-Path $extract 'release_full'
if (-not (Test-Path $src)) { $src = $extract }

$programPatterns = @('*.dll', '*.pdb', '*.deps.json', '*.runtimeconfig.json', 'web.config', '*.staticwebassets.endpoints.json')
foreach ($comp in $comps) {
    $from = Join-Path $src $comp
    if (-not (Test-Path $from)) { throw "Component $comp is not present in this release" }
    $to = Join-Path $Root $comp
    New-Item -ItemType Directory -Force -Path $to | Out-Null
    # Replace program files only; nimbus.proxy.toml, state files and plugins stay put.
    foreach ($pattern in $programPatterns) {
        Get-ChildItem -LiteralPath $to -Filter $pattern -File -ErrorAction SilentlyContinue | Remove-Item -Force
    }
    Copy-Item -Path (Join-Path $from '*') -Destination $to -Recurse -Force
}

$license = Join-Path $src 'LICENSE'
if (Test-Path $license) { Copy-Item -Path $license -Destination (Join-Path $Root 'LICENSE') -Force }

Remove-Item $extract -Recurse -Force
Set-Content -Path $marker -Value $tag -NoNewline
Write-Host "[AMP] installed Nimbus $tag ($Components) into $Root"
